export const TYSON=Object.freeze({name:'Mike Tyson',special:'Tiger Attack',kind:'tysonTiger',duration:2.15,range:1000,color:'#f6a03b',glow:'rgba(255,148,49,.4)'});
export const PIGEON='tysonPigeon';
export function tysonPose(f){const t=Math.max(0,f.stateTime||0),p=f.attackProgress||0;let i=0;if(f.state==='special')i=t<.75?15:0;else if(f.state==='punch')i=p<.23?8:p<.55?9:p<.8?10:11;else if(f.state==='kick')i=p<.25?0:13;else if(f.state==='ko')i=16;else if(['hurt','grabbed','beltHeld'].includes(f.state))i=14;else if(f.state==='block')i=23;else if(!f.grounded||['jump','fall'].includes(f.state))i=12;else if(['walk','run'].includes(f.state))i=4+Math.floor(t*9)%4;else i=Math.floor(t*4)%4;return {key:'miketyson',index:i};}
export function createTysonPigeon(f){return {kind:PIGEON,basic:true,owner:f.id,facing:f.facing,originX:f.x,x:f.x+55*f.facing,y:f.y+145,age:0,ttl:1.1,duration:1.1,active:true,delay:0,hitCount:0};}
export function createTysonTiger(f){return {kind:TYSON.kind,owner:f.id,facing:f.facing,originX:f.x,x:f.x,age:0,ttl:TYSON.duration,duration:TYSON.duration,active:true,delay:0,hitCount:0,fired:false};}
export function endTysonTiger(g,a,s){s.active=false;s.ttl=0;if(a){a.vx=0;a.actionRemaining=0;g.setState(a,a.hp>0?'idle':'ko');}}
export function updateTyson(g,s,a,b,dt){if(!a||!b){s.active=false;s.ttl=0;return;}if(s.kind===PIGEON){const old=s.x;s.x+=s.facing*650*dt;const lo=Math.min(old,s.x)-28,hi=Math.max(old,s.x)+28;if(b.x>=lo&&b.x<=hi&&Math.abs((b.y+105)-s.y)<100){if(g.hit(a,b,10,'punch',180,.20,old-s.facing*30)){s.hitCount=1;s.active=false;s.ttl=0;}}if(s.ttl<=0)s.active=false;return;}a.facing=s.facing;a.vx=0;if(s.ttl>1e-9){a.state='special';a.actionRemaining=Math.max(a.actionRemaining,s.ttl);}if(s.age>=.45){const old=s.x;s.x=s.originX+s.facing*(55+(s.age-.45)*590);if(!s.fired&&b.x>=Math.min(old,s.x)-85&&b.x<=Math.max(old,s.x)+85&&b.y<170&&(b.x-s.originX)*s.facing>=0){s.fired=true;if(g.hit(a,b,35,TYSON.kind,320,.32,s.originX))s.hitCount=1;}}if(s.ttl<=1e-9)endTysonTiger(g,a,s);}
export function drawTyson(s,ground,draw){if(s.kind===PIGEON){draw(17+Math.floor(s.age*15)%3,s.x,ground-s.y,s.facing,.9);return;}if(s.age>=.45&&s.age<2.05)draw(20+Math.floor(s.age*10)%3,s.x,ground,s.facing,1.35);}
